"use client";

import { useId, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { MailIcon } from "./icons";
import { InboxStep } from "./magic-link/inbox-step";
import { BusySpinner } from "./shared/busy-spinner";
import { EmailField } from "./shared/email-field";
import { FernhillMark } from "./shared/fernhill-mark";
import { OrDivider } from "./shared/or-divider";
import { type Provider, ProviderButtons } from "./shared/provider-buttons";
import { useEmailEntry } from "./shared/use-email-entry";
import { useTimers } from "./shared/use-timers";
import { Layer } from "./shared/stack-layer";

/**
 * Passwordless sign-in: two providers, a work email checked as you type with
 * a fix for likely typos, and a send button. Sending cross-fades to a
 * check-your-inbox step in the same grid cell, so the card never resizes.
 */
export function MagicLink({ className }: { className?: string }) {
  const titleId = useId();
  const entry = useEmailEntry();
  const { later } = useTimers();
  const [sent, setSent] = useState(false);
  const [busy, setBusy] = useState<"send" | Provider | null>(null);
  const [address, setAddress] = useState("");
  const [providerNote, setProviderNote] = useState("");

  const send = () => {
    const to = entry.attempt();
    if (!to) return;
    setBusy("send");
    later(() => {
      setAddress(to);
      setBusy(null);
      setSent(true);
    }, 700);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={cn("mx-auto max-w-sm", className)}>
      <div className="grid grid-cols-1 p-6">
        <Layer active={!sent}>
          <div className="flex flex-col gap-5">
            <div className="flex flex-col gap-3">
              <FernhillMark />
              <div className="flex flex-col gap-1">
                <h2 id={titleId} className="text-lg font-semibold">
                  Sign in without a password
                </h2>
                <p className="text-sm text-muted-foreground">We email you a link. Open it on this device and you are in.</p>
              </div>
            </div>
            <ProviderButtons
              busy={busy === "work" || busy === "sso" ? busy : null}
              disabled={busy !== null}
              onPick={(provider) => {
                setBusy(provider);
                setProviderNote("");
                later(() => {
                  setBusy(null);
                  setProviderNote("Your account opened in a new window. Finish there to come back signed in.");
                }, 1100);
              }}
            />
            <p aria-live="polite" className="text-sm text-muted-foreground empty:hidden">
              {providerNote}
            </p>
            <OrDivider label="or use your email" />
            <form
              noValidate
              className="flex flex-col gap-2"
              onSubmit={(event) => {
                event.preventDefault();
                send();
              }}
            >
              <EmailField entry={entry} disabled={busy !== null} />
              <Button type="submit" disabled={busy !== null} aria-busy={busy === "send"}>
                <BusySpinner busy={busy === "send"} icon={<MailIcon aria-hidden="true" className="size-4" />} />
                Email me a sign-in link
              </Button>
              <p aria-live="polite" className="sr-only">
                {busy === "send" ? "Sending the link" : ""}
              </p>
            </form>
            <p className="text-xs text-muted-foreground">
              By continuing you agree to the{" "}
              <Button variant="link" size="sm" asChild>
                <a href="#fernhill-terms">terms of service</a>
              </Button>{" "}
              and the{" "}
              <Button variant="link" size="sm" asChild>
                <a href="#fernhill-privacy">privacy notice</a>
              </Button>
              .
            </p>
          </div>
        </Layer>
        <Layer active={sent}>
          <InboxStep address={address || "you"} active={sent} onChangeEmail={() => setSent(false)} />
        </Layer>
      </div>
    </BlockFrame>
  );
}

