"use client";

import { useEffect, useRef, useState } from "react";

import { Button } from "@/components/ui/button";

import { CopyIcon, InboxIcon } from "../icons";
import { useCountdown } from "../shared/use-countdown";
import { EnvelopeArt } from "./envelope-art";

const SUBJECT = "Your Fernhill sign-in link";

/** Props for the check-your-inbox step. */
export interface InboxStepProps {
  address: string;
  /** True while the step shows. The envelope plays and the countdown starts each time it turns true. */
  active: boolean;
  onChangeEmail: () => void;
}

/**
 * The step after sending: the envelope plays once, then shortcuts to the
 * inbox, a way to change the address and a resend link that waits 30 seconds.
 */
export function InboxStep({ address, active, onChangeEmail }: InboxStepProps) {
  const heading = useRef<HTMLHeadingElement>(null);
  const resend = useCountdown(30);
  const [notice, setNotice] = useState("");
  const { restart } = resend;

  // A fresh visit to the step clears the last copy notice during render, not in an effect.
  const [wasActive, setWasActive] = useState(active);
  if (active !== wasActive) {
    setWasActive(active);
    if (active) setNotice("");
  }

  useEffect(() => {
    if (!active) return;
    restart();
    // The layer turns visible a moment after it activates; focus waits for it.
    const timer = setTimeout(() => heading.current?.focus(), 120);
    return () => clearTimeout(timer);
  }, [active, restart]);

  const copySubject = async () => {
    try {
      await navigator.clipboard.writeText(SUBJECT);
      setNotice(`Copied "${SUBJECT}". Paste it into your mail search.`);
    } catch {
      setNotice(`Search your mail for "${SUBJECT}".`);
    }
  };

  return (
    <div className="flex flex-col items-center gap-5 text-center">
      {active ? <EnvelopeArt /> : <div className="h-24" />}
      <div className="flex flex-col gap-1">
        <h3 ref={heading} tabIndex={-1} className="rounded-sm text-lg font-semibold outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background">
          Check your inbox
        </h3>
        <p className="text-sm text-pretty text-muted-foreground">
          We sent a sign-in link to <span className="font-medium break-all text-foreground">{address}</span>. It works once, for 15 minutes.
        </p>
      </div>
      <div className="grid w-full gap-2 @sm:grid-cols-2">
        <Button variant="outline" asChild>
          <a href={`mailto:${address}`}>
            <InboxIcon aria-hidden="true" className="size-4" />
            Open your mail app
          </a>
        </Button>
        <Button type="button" variant="outline" onClick={copySubject}>
          <CopyIcon aria-hidden="true" className="size-4" />
          Copy the subject
        </Button>
      </div>
      <p aria-live="polite" className="min-h-5 text-sm text-muted-foreground">
        {notice}
      </p>
      <div className="flex w-full flex-wrap items-center justify-between gap-2 text-sm">
        <Button type="button" variant="link" size="sm" onClick={onChangeEmail}>
          Use a different email
        </Button>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          disabled={resend.left > 0}
          onClick={() => {
            resend.restart();
            setNotice(`We sent a fresh link to ${address}.`);
          }}
        >
          {resend.left > 0 ? `Resend in ${resend.left} s` : "Resend the link"}
        </Button>
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";

/**
 * Counts down whole seconds from `start` each time `restart` runs, for a
 * resend link that waits before it can be used again.
 */
export function useCountdown(start: number) {
  const [left, setLeft] = useState(0);

  useEffect(() => {
    if (left <= 0) return;
    const timer = setTimeout(() => setLeft((value) => value - 1), 1000);
    return () => clearTimeout(timer);
  }, [left]);

  const restart = useCallback(() => setLeft(start), [start]);
  const stop = useCallback(() => setLeft(0), []);

  return { left, restart, stop };
}

"use client";

import { motion, useReducedMotion } from "motion/react";

// The flap as one line: folded up while the letter drops in, then shut.
const OPEN = "M16 37L60 7L104 37";
const CLOSED = "M16 37L60 67L104 37";

/**
 * An envelope that plays once: the letter drops in, the flap folds shut and
 * a check settles on the corner. Reduced motion shows the closed envelope.
 */
export function EnvelopeArt() {
  const reduce = useReducedMotion();
  const instant = { duration: 0 };

  return (
    <svg viewBox="0 0 120 96" aria-hidden="true" className="h-24 w-32">
      <rect x="14" y="34" width="92" height="56" rx="6" className="fill-chart-1/15 stroke-chart-1" strokeWidth="2" />
      <motion.g
        initial={reduce ? { y: 20, opacity: 1 } : { y: -34, opacity: 0 }}
        animate={{ y: 20, opacity: 1 }}
        transition={reduce ? instant : { type: "spring", stiffness: 220, damping: 22 }}
      >
        <rect x="26" y="0" width="68" height="44" rx="4" className="fill-card stroke-chart-3" strokeWidth="2" />
        <path d="M36 14h40M36 24h48M36 34h28" className="stroke-chart-3" strokeWidth="2" strokeLinecap="round" />
      </motion.g>
      <path d="M14 40l46 28 46-28v44a6 6 0 0 1-6 6H20a6 6 0 0 1-6-6Z" className="fill-card stroke-chart-1" strokeWidth="2" strokeLinejoin="round" />
      <motion.path
        fill="none"
        className="stroke-chart-1"
        strokeWidth="2"
        strokeLinejoin="round"
        initial={{ d: reduce ? CLOSED : OPEN }}
        animate={{ d: CLOSED }}
        transition={reduce ? instant : { delay: 0.45, duration: 0.35, ease: "easeInOut" }}
      />
      <motion.g
        initial={reduce ? { scale: 1, opacity: 1 } : { scale: 0, opacity: 0 }}
        animate={{ scale: 1, opacity: 1 }}
        transition={reduce ? instant : { delay: 0.85, type: "spring", stiffness: 380, damping: 18 }}
      >
        <circle cx="100" cy="34" r="12" className="fill-chart-2" />
        <path d="M94.5 34.5l3.5 3.5 7-7.5" fill="none" className="stroke-primary-foreground" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
      </motion.g>
    </svg>
  );
}

import type { ReactNode } from "react";

import { LoaderIcon } from "../icons";

/**
 * The spinner of a button that keeps its label while it works. With `icon`,
 * the spinner takes the icon's place at the same size. Without one, it sits in
 * the button's leading padding, so the label stays centred and the button's
 * width never moves; that button needs `relative`.
 */
export function BusySpinner({ busy, icon }: { busy: boolean; icon?: ReactNode }) {
  const spinner = <LoaderIcon aria-hidden="true" className="size-4 motion-safe:animate-spin" />;
  if (icon !== undefined) return busy ? spinner : icon;
  return (
    <span aria-hidden="true" className="pointer-events-none absolute inset-y-0 start-3 flex items-center">
      {busy ? spinner : null}
    </span>
  );
}

"use client";

import { useId } from "react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

import type { EmailEntry } from "./use-email-entry";

/** Props for a labelled email field that explains its own errors. */
export interface EmailFieldProps {
  entry: EmailEntry;
  label?: string;
  autoFocus?: boolean;
  disabled?: boolean;
}

/**
 * An email field with its label, an inline error under it, and a one-tap fix
 * when the domain looks misspelt. The hint says Enter again keeps the address.
 */
export function EmailField({ entry, label = "Work email", autoFocus, disabled }: EmailFieldProps) {
  const id = useId();
  const noteId = `${id}-note`;
  const note = entry.error ?? (entry.suggestion ? "suggestion" : null);

  return (
    <div className="flex flex-col gap-1.5">
      <label htmlFor={id} className="text-sm font-medium">
        {label}
      </label>
      <Input
        id={id}
        type="email"
        autoComplete="email"
        placeholder="name@yourclinic.org"
        autoFocus={autoFocus}
        disabled={disabled}
        value={entry.value}
        onChange={(event) => entry.setValue(event.target.value)}
        onBlur={entry.blur}
        aria-invalid={entry.error ? true : undefined}
        aria-describedby={note ? noteId : undefined}
      />
      <div id={noteId} aria-live="polite" className="min-h-5 text-sm">
        {entry.error ? <p className="text-destructive">{entry.error}</p> : null}
        {entry.suggestion ? (
          <p className="text-muted-foreground">
            Did you mean{" "}
            <Button type="button" variant="link" size="sm" onClick={entry.accept}>
              {entry.suggestion}
            </Button>
            ? Press Enter again to keep what you typed.
          </p>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";

import { checkEmail } from "./email-check";

/**
 * Holds a typed email address and decides whether a submit may go ahead.
 * A malformed address blocks. A likely typo blocks once and shows the fix;
 * a second submit sends the address as typed.
 */
export function useEmailEntry(initial = "") {
  const [value, setRawValue] = useState(initial);
  const [touched, setTouched] = useState(false);
  const [typoShown, setTypoShown] = useState(false);
  const check = checkEmail(value);

  const setValue = (next: string) => {
    setRawValue(next);
    setTypoShown(false);
  };

  /** Returns the address to send to, or null when the person must fix it first. */
  const attempt = (): string | null => {
    setTouched(true);
    if (check.state === "empty" || check.state === "invalid") return null;
    if (check.state === "typo" && !typoShown) {
      setTypoShown(true);
      return null;
    }
    return value.trim();
  };

  const error = touched ? (check.state === "empty" ? "Enter your work email." : check.state === "invalid" ? check.message : null) : null;
  const suggestion = check.state === "typo" && typoShown ? check.suggestion : null;

  return {
    value,
    setValue,
    error,
    suggestion,
    attempt,
    blur: () => {
      if (value.trim()) setTouched(true);
    },
    accept: () => {
      if (suggestion) setValue(suggestion);
    },
    reset: () => {
      setRawValue(initial);
      setTouched(false);
      setTypoShown(false);
    },
  };
}

/** The state and actions `useEmailEntry` returns. */
export type EmailEntry = ReturnType<typeof useEmailEntry>;

/** What a typed email address is: empty, malformed, likely misspelt, or fine. */
export type EmailCheck =
  | { state: "empty" }
  | { state: "invalid"; message: string }
  | { state: "typo"; suggestion: string }
  | { state: "ok" };

// Domains people mistype often, and the one they meant.
const DOMAIN_FIXES = new Map(Object.entries({
  "gmial.com": "gmail.com",
  "gmai.com": "gmail.com",
  "gamil.com": "gmail.com",
  "gmail.co": "gmail.com",
  "hotmial.com": "hotmail.com",
  "outlok.com": "outlook.com",
  "outlook.co": "outlook.com",
  "yaho.com": "yahoo.com",
  "icloud.co": "icloud.com",
  "fernhil.clinic": "fernhill.clinic",
  "fernhill.clinc": "fernhill.clinic",
}));

const TLD_FIXES = new Map(Object.entries({ con: "com", cmo: "com", ocm: "com", nte: "net", ogr: "org" }));

const WELL_FORMED = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

/**
 * Reads a typed address. A well-formed address on a domain people often
 * mistype comes back with the address they most likely meant.
 */
export function checkEmail(raw: string): EmailCheck {
  const value = raw.trim();
  if (!value) return { state: "empty" };
  if (!value.includes("@")) return { state: "invalid", message: "Add the @ and the domain, such as name@clinic.org." };
  if (!WELL_FORMED.test(value)) return { state: "invalid", message: "Check the part after the @. It needs a domain such as clinic.org." };

  const at = value.lastIndexOf("@");
  const name = value.slice(0, at);
  const domain = value.slice(at + 1);
  const lower = domain.toLowerCase();
  const fixed = DOMAIN_FIXES.get(lower);
  if (fixed) return { state: "typo", suggestion: `${name}@${fixed}` };

  const dot = lower.lastIndexOf(".");
  const tld = TLD_FIXES.get(lower.slice(dot + 1));
  if (tld) return { state: "typo", suggestion: `${name}@${lower.slice(0, dot + 1)}${tld}` };
  return { state: "ok" };
}

